function begin(continuing=false){const saved=E.store.get(SAVE_KEY,null);state=continuing&&saved&&saved.version===1?Object.assign(freshState(),saved):freshState();state.flags=state.flags||{};state.inventory=state.inventory||['edge'];state.visited=state.visited||[];state.hp=maxHP();state.mp=maxMP();state.charges=2;started=true;mode='play';game.uiPaused=false;cache={};hero=null;show('title-screen',false);show('modal',false);show('hud');show('objective');show('pause-btn');document.body.classList.add('playing');sound.start('explore');enterRoom(state.checkpoint.room,state.checkpoint.x,state.checkpoint.z);game.input.clear();$('screen').focus();if(!continuing)toast('THE LAST BELLKEEPER','Ilyra','Reach the abbey. Follow the light. Keep the dead from finding their voice.',4.6);}
